theme_designer_bridge.codigo_completo:
/*
<Group description="🎨 Cores do Tema (Pop Retro)" selector=":root">
  <Variable name="cor.primaria" description="Cor Principal (Destaques)" type="color" default="#FF4500" value="#FF4500"/>
  <Variable name="cor.secundaria" description="Cor Secundária (Efeito Matrix)" type="color" default="#00FF41" value="#00FF41"/>
  <Variable name="cor.fundo" description="Cor de Fundo (Background)" type="color" default="#F4F4F4" value="#F4F4F4"/>
  <Variable name="cor.borda" description="Cor das Bordas dos Cartuchos" type="color" default="#000000" value="#000000"/>
</Group>
*/

:root {
  --primary: $(cor.primaria);
  --secondary: $(cor.secundaria);
  --bg-light: $(cor.fundo);
  --border-pixel: 4px solid $(cor.borda);
  --font-pixel: 'Press Start 2P', cursive;
}

float_and_blink_animations.float_item:
@keyframes floatItem {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
.quest-icon { animation: floatItem 2s steps(4) infinite; }

float_and_blink_animations.pulse_cookie:
@keyframes pulseCookie {
  0% { transform: scale(1); }
  50% { transform: scale(1.1); }
  100% { transform: scale(1); }
}
.cookie-icon { animation: pulseCookie 1s steps(2) infinite; }
